content.solution_code:
class Spell {
  constructor(name, manaCost) {
    if (manaCost < 0) {
      throw new Error("Mana cost cannot be negative.");
    }
    this.name = name;
    this.manaCost = manaCost;
  }

  cast(target) {
    return `${this.name} is cast on ${target}. (Base spell effect)`;
  }
}

class Fireball extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    if (damage <= 0) {
      throw new Error("Fireball damage must be positive.");
    }
    this.damage = damage;
  }

  cast(target) {
    return `${this.name} blasts ${target} for ${this.damage} fire damage!`;
  }
}

class IceShard extends Spell {
  constructor(name, manaCost, damage, slowPercentage) {
    super(name, manaCost);
    if (damage <= 0) {
      throw new Error("Ice Shard damage must be positive.");
    }
    if (slowPercentage < 0 || slowPercentage > 100) {
      throw new Error("Slow percentage must be between 0 and 100.");
    }
    this.damage = damage;
    this.slowPercentage = slowPercentage;
  }

  cast(target) {
    return `${this.name} freezes ${target} for ${this.damage} ice damage and slows by ${this.slowPercentage}%!`;
  }
}

